package com.bedlessfighter.necroManager.commands;
import com.bedlessfighter.necroManager.managers.*;import org.bukkit.Bukkit;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.jetbrains.annotations.NotNull;
public final class IgnoreCommand implements CommandExecutor {
 @Override public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String[] a){if(!(s instanceof Player p)){MessageManager.send(s,"messages.player-required","&cOnly players can ignore players.");return true;}if(a.length!=1){MessageManager.sendRaw(s,"&cUsage: /ignore <player>");return true;}Player t=Bukkit.getPlayerExact(a[0]);if(t==null){MessageManager.send(s,"messages.player-not-found","&cPlayer not online.");return true;}if(t.equals(p)){MessageManager.sendRaw(s,"&cYou cannot ignore yourself.");return true;}boolean ignored=ChatSocialManager.toggleIgnore(p.getUniqueId(),t.getUniqueId());MessageManager.sendRaw(s,ignored?"&aNow ignoring "+t.getName()+".":"&eNo longer ignoring "+t.getName()+".");return true;}
}